<script setup lang="ts">
import {ref,computed,onMounted,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,requestKey,parseInput} from '../api/client'
import {useGuest} from '../stores/guest'
import {names,display,type TrainingSession,type Value,type Attempt} from '../types'
import TaskProblem from '../components/TaskProblem.vue'
import WorkedExplanation from '../components/WorkedExplanation.vue'
const route=useRoute(),router=useRouter(),guest=useGuest(),session=ref<TrainingSession|null>(null),answer=ref<Value>(null),answerText=ref(''),scratchpad=ref(''),confidence=ref(''),busy=ref(false),error=ref(''),queryText=ref(''),intro=ref(false),draftStatus=ref(''),reflection=ref(''),note=ref(''),savedReflection=ref(false)
const task=computed(()=>session.value?.current),practice=computed(()=>session.value?.mode==='mixed'||session.value?.mode==='focus'),lesson=computed(()=>guest.families.find(f=>f.id===task.value?.family)?.lesson),result=computed(()=>task.value?.result)
let saveTimer:ReturnType<typeof setTimeout>|undefined;let loading=false;let queryKey=''
function hydrate(){loading=true;const t=task.value;let cached:{answer?:Value;answerText?:string;scratchpad?:string;confidence?:string}|null=null;try{cached=t&&!t.submitted?JSON.parse(localStorage.getItem('hf-draft-'+t.instance_id)??'null'):null}catch{/* Ignore an invalid browser draft. */}answer.value=cached?.answer??t?.draft.answer??null;answerText.value=typeof answer.value==='number'?String(answer.value):Array.isArray(answer.value)?answer.value.join(', '):'';answerText.value=cached?.answerText??answerText.value;scratchpad.value=cached?.scratchpad??t?.draft.scratchpad??'';confidence.value=cached?.confidence??(t?.draft.confidence!=null?String(t.draft.confidence):'');intro.value=!!(t&&practice.value&&!localStorage.getItem('hf-seen-'+t.family));savedReflection.value=false;queryText.value='';draftStatus.value='';queueMicrotask(()=>{loading=false})}
async function load(){busy.value=true;try{session.value=await api<TrainingSession>('/sessions/'+route.params.id);if(session.value.state==='active'&&!task.value)session.value=await api<TrainingSession>('/sessions/'+route.params.id+'/next','POST');hydrate()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function persistDraft(){if(!task.value||task.value.submitted||!session.value||session.value.state!=='active')return;try{let a=answer.value;if(task.value.family==='induction'&&answerText.value.trim()){try{a=parseInput(answerText.value,task.value.render.input_kind==='list')}catch{/* Keep the editable text locally until valid. */}}await api('/instances/'+task.value.instance_id+'/draft','PATCH',{scratchpad:scratchpad.value,answer:a,confidence:confidence.value===''?null:Number(confidence.value)});localStorage.setItem('hf-answer-'+task.value.instance_id,answerText.value);draftStatus.value='Draft saved'}catch(e){draftStatus.value='Draft not saved. '+(e as Error).message}}
watch([answer,answerText,scratchpad,confidence],()=>{if(loading||task.value?.submitted)return;if(task.value)localStorage.setItem('hf-draft-'+task.value.instance_id,JSON.stringify({answer:answer.value,answerText:answerText.value,scratchpad:scratchpad.value,confidence:confidence.value}));draftStatus.value='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(persistDraft,500)},{deep:true})
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function submit(){await run(async()=>{if(!task.value)return;clearTimeout(saveTimer);await persistDraft();let value=answer.value;if(task.value.family==='induction')value=parseInput(answerText.value,task.value.render.input_kind==='list');const a=await api<Attempt>('/instances/'+task.value.instance_id+'/submit','POST',{answer:value,confidence:confidence.value===''?null:Number(confidence.value)});localStorage.removeItem('hf-draft-'+task.value.instance_id);localStorage.removeItem('hf-answer-'+task.value.instance_id);task.value.submitted=true;task.value.result=a;task.value.feedback_sealed=a.sealed;if(a.task)session.value!.current=a.task;session.value=await api<TrainingSession>('/sessions/'+route.params.id);await guest.refresh();document.getElementById('feedback')?.focus()})}
async function next(){await run(async()=>{session.value=await api<TrainingSession>('/sessions/'+route.params.id+'/next','POST');hydrate();window.scrollTo({top:0,behavior:'instant'})})}
async function revealHint(){await run(async()=>{if(!task.value)return;const r=await api<{hint:string;hints_used:number}>('/instances/'+task.value.instance_id+'/hints','POST',{index:task.value.hints_used});task.value.hints=[...(task.value.hints??[]),r.hint];task.value.hints_used=r.hints_used})}
async function query(){await run(async()=>{if(!task.value)return;const input=parseInput(queryText.value,task.value.render.input_kind==='list');if(!queryKey)queryKey=requestKey();const r=await api<{queries:typeof task.value.queries}>('/instances/'+task.value.instance_id+'/queries','POST',{input},queryKey);task.value.queries=r.queries;queryKey='';queryText.value=''})}
watch(queryText,()=>{queryKey=''})
async function pause(){await run(async()=>{await persistDraft();session.value=await api<TrainingSession>('/sessions/'+route.params.id,'PATCH',{state:'paused'});await guest.refresh();await router.push('/')})}
async function resume(){await run(async()=>{session.value=await api<TrainingSession>('/sessions/'+route.params.id,'PATCH',{state:'active'});if(!task.value)session.value=await api<TrainingSession>('/sessions/'+route.params.id+'/next','POST');hydrate()})}
async function abandon(){if(!confirm('Abandon this session? Completed attempts remain in your notebook.'))return;await run(async()=>{await api('/sessions/'+route.params.id,'PATCH',{state:'abandoned'});await guest.refresh();await router.push('/')})}
function closeIntro(){if(task.value)localStorage.setItem('hf-seen-'+task.value.family,'1');intro.value=false}
async function saveReflection(){await run(async()=>{await api('/attempts/'+result.value?.id+'/reflection','PATCH',{category:reflection.value||null,note:note.value});savedReflection.value=true})}
async function release(){if(!confirm('Release the assessment solutions? This exposes assessment content and will be recorded on later checks and probes.'))return;await run(async()=>{session.value=await api<TrainingSession>('/sessions/'+route.params.id+'/release','POST',{confirm:true})})}
onMounted(async()=>{await load();if(task.value&&!answerText.value)answerText.value=localStorage.getItem('hf-answer-'+task.value.instance_id)??''})
onBeforeUnmount(()=>{clearTimeout(saveTimer);void persistDraft()})
</script>
<template><div v-if="error" role="alert" class="error">{{error}} <button v-if="!session" @click="load">Retry</button></div><div v-if="!session&&!error" role="status">Opening your session…</div><template v-if="session"><div class="exercise-top"><RouterLink to="/" class="back-link">← Your notebook</RouterLink><div class="actions" v-if="session.state==='active'"><button class="text-button" @click="pause" :disabled="busy">Pause & save</button><button class="text-button muted" @click="abandon" :disabled="busy">Abandon</button></div></div>
 <div v-if="session.state==='paused'" class="empty-state"><span class="eyebrow">A BOOKMARK, NOT A SETBACK</span><h1>Right where you left off.</h1><p>Your observations, hints, answers, and scratchpad are saved.</p><button class="primary" @click="resume" :disabled="busy">Resume session →</button></div>
 <div v-else-if="session.state==='abandoned'" class="empty-state"><h1>Session closed.</h1><RouterLink class="button" to="/">Start a new page →</RouterLink></div>
 <template v-else><div class="session-heading"><div><span class="eyebrow">{{session.mode==='mixed'?'MIXED PRACTICE':session.mode==='focus'?'FOCUSED PRACTICE':session.mode==='check'?'UNAIDED CHECK':'EXPLORATORY PROBE'}}</span><h1>{{session.state==='completed'?'A page completed.':task?names[task.family]:'Your next problem'}}</h1></div><div class="session-count"><strong>{{session.completed}}</strong> / {{session.total}}<span>PROBLEMS COMPLETE</span></div></div><div class="session-track" :aria-label="`${session.completed} of ${session.total} complete`"><span v-for="n in session.total" :key="n" :class="{filled:n<=session.completed,current:n===session.completed+1}"></span></div>
 <div v-if="!practice" class="notice"><strong>{{session.mode==='check'?'Fixed difficulty. Independent answers.':'Presentation transfer, not broad intelligence transfer.'}}</strong><p>{{session.mode==='check'?'Ten balanced problems at level 2. No hints or tutor. Results appear at completion; solutions stay sealed until you choose to release them.':'Six ordering tasks use a scheduling presentation withheld from practice. This is an exploratory test of a related presentation, without hints.'}}</p><span v-if="session.manifest.prior_releases||session.manifest.repeated_form" class="micro">Prior assessment exposure or repeated form recorded. Interpret results with care.</span></div>
 <section v-if="session.state==='completed'" class="completion-panel"><span class="eyebrow">WORK DONE. SOMETHING LEARNED.</span><h2>{{practice?'Take a moment to reflect.':'Your aggregate results are ready.'}}</h2><p>{{practice?'Every first answer is saved, along with the help you used. Revisit a mistake or let the next session bring you a fresh related example.':'View your results in Progress. Item solutions stay sealed until explicitly released; exposure is recorded.'}}</p><div class="actions"><RouterLink class="button primary" to="/progress">See progress →</RouterLink><RouterLink class="button" to="/review">Open review</RouterLink><button v-if="!practice&&!session.released" @click="release" :disabled="busy">Release assessment solutions</button></div></section>
 <div v-if="task" class="exercise-layout"><section class="task-panel"><div class="task-header"><span class="eyebrow">PROBLEM {{task.position.toString().padStart(2,'0')}} <span class="muted">/ LEVEL {{task.difficulty}}</span></span><button v-if="practice" class="text-button" @click="intro=!intro">{{intro?'Close guide':'How this works ↗'}}</button></div><div v-if="intro&&lesson" class="lesson"><span class="eyebrow">FIRST, A WORKED EXAMPLE · NOT SCORED</span><h3>{{lesson.principle}}</h3><p>{{lesson.example}}</p><p>{{lesson.strategy}}</p><button @click="closeIntro">Got it, try the problem →</button></div><h2 class="task-question">{{task.instructions}}</h2>
 <TaskProblem :task="task" v-model="answer" :locked="task.submitted"/>
 <section v-if="task.family==='hypothesis'" class="hypothesis-lab"><h3>Your experiment log</h3><p class="muted">Choose inputs that tell the candidate rules apart. Up to 12 queries; no speed score.</p><table v-if="task.queries.length"><thead><tr><th>Query</th><th>Input</th><th>Observed output</th></tr></thead><tbody><tr v-for="(q,i) in task.queries" :key="i"><td>{{i+1}}</td><td>{{display(q.input)}}</td><td>{{display(q.output)}}</td></tr></tbody></table><p v-else class="empty-inline">No observations yet. Try a query before choosing a rule.</p><form v-if="!task.submitted" class="query-form" @submit.prevent="query"><label>Experiment input <input v-model="queryText" :placeholder="task.render.input_kind==='list'?'3, -2, 4, 1':'A whole number from −10 to 10'" :disabled="busy"></label><button :disabled="busy||!queryText.trim()">Run query →</button></form></section>
 <form v-if="!task.submitted" @submit.prevent="submit" class="submit-area"><label v-if="task.family==='induction'" class="output-field">Your predicted output <input v-model="answerText" :placeholder="task.render.input_kind==='list'?'Values separated by commas':'A whole number'" autocomplete="off"></label><label class="confidence">Confidence <span class="muted">(optional, before feedback)</span><select v-model="confidence"><option value="">Prefer not to say</option><option value="0.25">25% likely correct</option><option value="0.5">50% likely correct</option><option value="0.75">75% likely correct</option><option value="1">100% likely correct</option></select></label><div class="actions"><button class="primary" :disabled="busy">{{busy?'Saving…':'Submit answer'}} <span>→</span></button><span class="micro">FIRST ANSWERS ARE SAVED ONCE.</span></div></form>
 <section v-if="task.submitted&&result" id="feedback" tabindex="-1" class="feedback"><div v-if="!result.sealed" class="result-banner" role="status" :class="result.correct?'correct':'incorrect'"><strong>{{result.correct?'Correct. Your reasoning holds.':'A useful place to look again.'}}</strong><span>{{result.assisted?'Assisted attempt · hints recorded':'Independent first attempt'}}</span></div><p v-else class="notice" role="status">Answer saved. {{session.state==='completed'?'Aggregate results are available in Progress.':'Feedback will wait until the check is complete.'}} Item solutions remain sealed.</p><WorkedExplanation v-if="result.explanation" :explanation="result.explanation"/><div v-if="!result.sealed" class="reflection"><label>What would you keep or change? <span class="muted">(optional)</span><select v-model="reflection"><option value="">Choose a reflection</option><option v-for="c in ['missing constraint','untested alternative','wrong rule','execution mistake','unclear instruction','other']" :key="c">{{c}}</option></select></label><label>Your note<textarea v-model="note" maxlength="3000" rows="2" placeholder="One thought to carry into the next problem."></textarea></label><button @click="saveReflection" :disabled="busy">{{savedReflection?'Reflection saved':'Save reflection'}}</button></div><div class="actions after-feedback"><button v-if="session.state!=='completed'" class="primary" :disabled="busy" @click="next">Next problem →</button><RouterLink v-if="!result.sealed" class="button" :to="'/discussion/'+result.id">Discuss this problem ↗</RouterLink></div></section>
 </section><aside class="thinking-column"><details open class="secondary-tools"><summary>Your scratchpad & hints</summary><section class="scratchpad"><span class="eyebrow">ROOM TO THINK</span><label for="scratch">Your scratchpad</label><textarea id="scratch" v-model="scratchpad" maxlength="6000" rows="10" :readonly="task.submitted" placeholder="Trace a connection. Test an assumption. Leave yourself a note."></textarea><p class="micro" role="status">{{draftStatus||'SAVED WITH THIS PROBLEM. PRIVATE BY DEFAULT.'}}</p></section><section v-if="practice" class="strategy-panel"><span class="eyebrow">A LITTLE SUPPORT</span><h3>Get a foothold.</h3><p>Hints reveal a little more each time. Using one marks this attempt as assisted.</p><ol v-if="task.hints?.length" class="hint-list"><li v-for="(h,i) in task.hints" :key="i">{{h}}</li></ol><button v-if="!task.submitted&&task.hints_used<3" :disabled="busy" @click="revealHint">Reveal hint {{task.hints_used+1}} / 3 →</button><p class="micro" v-if="task.hints_used===3">ALL THREE HINTS REVEALED</p></section><div class="scheduler-note"><span class="eyebrow">WHY THIS PROBLEM?</span><p>{{task.rationale}}</p></div></details></aside></div>
 </template></template></template>
